
# ============================================================
# RAG vs BASE LLM - EVALUATION SCRIPT
# ============================================================
#
# This script evaluates the answers generated by the Base LLM
# and RAG LLM using four evaluation methods:
#
# 1. Exact Match
# 2. Token-level F1
# 3. Semantic Similarity
# 4. LLM Judge
#
# The results are saved in evaluation_results1.json.
#
# ============================================================


# ------------------------------------------------------------
# 1. IMPORT LIBRARIES
# ------------------------------------------------------------

import json
import re
import random
import time

from pathlib import Path
from collections import Counter

# Used for semantic similarity
from sentence_transformers import SentenceTransformer, util

# Used to communicate with Gemini
from google import genai
from google.genai import types
from google.genai.errors import ServerError


# ------------------------------------------------------------
# 2. CONFIGURATION
# ------------------------------------------------------------

# Input file containing the Base LLM and RAG LLM answers
INPUT_PATH = Path(
    r"C:\Users\Nathan\Videos\AI Project\RAG_vs_Base_LLM\raw_results.json"
)

# Output file containing evaluation scores
OUTPUT_PATH = Path(
    r"C:\Users\Nathan\Videos\AI Project\RAG_vs_Base_LLM\evaluation_results1.json"
)

# Sentence Transformer model for semantic similarity
EMBEDDING_MODEL_NAME = "all-MiniLM-L6-v2"

# Gemini model used as the LLM judge
JUDGE_MODEL = "gemini-3.1-flash-lite"


# ------------------------------------------------------------
# 3. INITIALIZE MODELS
# ------------------------------------------------------------

# Gemini automatically reads GEMINI_API_KEY from environment variables
client = genai.Client()

# Load the sentence embedding model
# This model runs locally and does not use the Gemini API
print("Loading sentence embedding model...")

embedding_model = SentenceTransformer(EMBEDDING_MODEL_NAME)

print("Embedding model loaded successfully.")


# ------------------------------------------------------------
# 4. LOAD RAW RESULTS
# ------------------------------------------------------------

def load_results():

    # Open and read the JSON input file
    with open(INPUT_PATH, "r", encoding="utf-8") as file:
        results = json.load(file)

    # Make sure the file contains a list of questions
    if not isinstance(results, list):
        raise ValueError("The input JSON must contain a list.")

    print(f"Loaded {len(results)} questions.")

    return results


# ------------------------------------------------------------
# 5. TEXT NORMALIZATION
# ------------------------------------------------------------

def normalize_text(text):

    # Convert the answer to lowercase
    text = text.lower()

    # Remove punctuation
    text = re.sub(r"[^\w\s]", "", text)

    # Remove extra spaces
    text = " ".join(text.split())

    return text


# ------------------------------------------------------------
# 6. EXACT MATCH
# ------------------------------------------------------------

def exact_match(prediction, ground_truth):

    # Normalize both answers before comparing them
    prediction = normalize_text(prediction)
    ground_truth = normalize_text(ground_truth)

    # Return 1 if they match, otherwise return 0
    if prediction == ground_truth:
        return 1

    return 0


# ------------------------------------------------------------
# 7. TOKEN-LEVEL F1
# ------------------------------------------------------------

def token_f1(prediction, ground_truth):

    # Normalize and split both answers into individual words
    prediction_tokens = normalize_text(prediction).split()
    ground_truth_tokens = normalize_text(ground_truth).split()

    # Handle empty answers
    if not prediction_tokens or not ground_truth_tokens:
        return 0.0

    # Count how many times each word appears
    prediction_counts = Counter(prediction_tokens)
    ground_truth_counts = Counter(ground_truth_tokens)

    # Find the number of overlapping words
    common_words = prediction_counts & ground_truth_counts

    overlap = sum(common_words.values())

    # If there are no matching words, F1 is zero
    if overlap == 0:
        return 0.0

    # Calculate precision and recall
    precision = overlap / len(prediction_tokens)
    recall = overlap / len(ground_truth_tokens)

    # Calculate F1 score
    f1 = (2 * precision * recall) / (precision + recall)

    return f1


# ------------------------------------------------------------
# 8. SEMANTIC SIMILARITY
# ------------------------------------------------------------

def semantic_similarity(prediction, ground_truth):

    # Convert both answers into numerical embeddings
    prediction_embedding = embedding_model.encode(
        prediction,
        convert_to_tensor=True
    )

    ground_truth_embedding = embedding_model.encode(
        ground_truth,
        convert_to_tensor=True
    )

    # Calculate cosine similarity between the embeddings
    similarity = util.cos_sim(
        prediction_embedding,
        ground_truth_embedding
    )

    # Convert the result into a regular Python number
    return float(similarity.item())


# ------------------------------------------------------------
# 9. GEMINI API RETRY FUNCTION
# ------------------------------------------------------------

def generate_judge_response(prompt):

    # Maximum number of attempts, including the first attempt
    max_retries = 5

    for attempt in range(max_retries):

        try:

            # Send the prompt to Gemini
            response = client.models.generate_content(
                model=JUDGE_MODEL,
                contents=prompt,
                config=types.GenerateContentConfig(
                    response_mime_type="application/json"
                )
            )

            return response

        except ServerError as error:

            # Only retry temporary 503 errors
            error_code = getattr(error, "code", None)

            if error_code != 503 or attempt == max_retries - 1:
                raise

            # Wait 2, 4, 8, and then 16 seconds
            wait_time = 2 ** (attempt + 1)

            print(
                f"Gemini temporarily unavailable (503). "
                f"Retrying in {wait_time} seconds..."
            )

            time.sleep(wait_time)


# ------------------------------------------------------------
# 10. LLM JUDGE
# ------------------------------------------------------------

def judge_answers(question, ground_truth, base_answer, rag_answer):

    # Randomize the order of answers to reduce position bias.
    # The judge sees Answer A and Answer B, not Base and RAG.
    answers = [
        ("base", base_answer),
        ("rag", rag_answer)
    ]

    random.shuffle(answers)

    answer_a = answers[0][1]
    answer_b = answers[1][1]

    # Create the evaluation prompt
    prompt = f"""
You are an impartial evaluator comparing two answers to a question.

Evaluate both answers using the supplied ground truth.

QUESTION:
{question}

GROUND TRUTH:
{ground_truth}

ANSWER A:
{answer_a}

ANSWER B:
{answer_b}

Evaluate each answer using these three criteria:

1. Factual Correctness:
   Does the answer provide factually correct information
   according to the ground truth?

2. Completeness:
   Does the answer include all the important information
   required to answer the question?

3. Relevance:
   Does the answer directly address the question without
   unnecessary or unrelated information?

Give each criterion a score from 1 to 5.

Scoring guide:
1 = Very poor
2 = Poor
3 = Acceptable
4 = Good
5 = Excellent

Use the ground truth as the reference.
Do not reward an answer for adding unsupported information.

Return your evaluation in this exact JSON structure:

{{
    "answer_a": {{
        "factual_correctness": 1,
        "completeness": 1,
        "relevance": 1
    }},
    "answer_b": {{
        "factual_correctness": 1,
        "completeness": 1,
        "relevance": 1
    }},
    "reasoning": "Briefly explain the evaluation."
}}

Return valid JSON only.
"""

    # Send the prompt to Gemini with retry protection
    response = generate_judge_response(prompt)

    # Convert Gemini's JSON response into a Python dictionary
    judge_result = json.loads(response.text)

    # Map the anonymous scores back to their original models
    scores = {}

    scores[answers[0][0]] = judge_result["answer_a"]
    scores[answers[1][0]] = judge_result["answer_b"]

    # Return scores with the original model names
    return {
        "base": scores["base"],
        "rag": scores["rag"],
        "reasoning": judge_result["reasoning"],

        # Record which model was presented first
        # This helps with later analysis
        "presentation_order": [
            answers[0][0],
            answers[1][0]
        ]
    }


# ------------------------------------------------------------
# 11. EVALUATE ALL QUESTIONS
# ------------------------------------------------------------

def evaluate_results(results):

    evaluated_results = []

    total_questions = len(results)

    for index, item in enumerate(results):

        print(
            f"\nEvaluating question {index + 1}/{total_questions}..."
        )

        # Retrieve the question and answers from the input JSON
        question = item["question"]
        ground_truth = item["ground_truth"]
        
        base_answer = item["base"]["answer"]
        rag_answer = item["rag"]["answer"]

        # ----------------------------------------------------
        # AUTOMATIC EVALUATION METRICS
        # ----------------------------------------------------

        # Evaluate Base LLM answer
        base_exact = exact_match(base_answer, ground_truth)
        base_f1 = token_f1(base_answer, ground_truth)
        base_similarity = semantic_similarity(
            base_answer,
            ground_truth
        )

        # Evaluate RAG LLM answer
        rag_exact = exact_match(rag_answer, ground_truth)
        rag_f1 = token_f1(rag_answer, ground_truth)
        rag_similarity = semantic_similarity(
            rag_answer,
            ground_truth
        )

        # ----------------------------------------------------
        # LLM JUDGE EVALUATION
        # ----------------------------------------------------

        judge_result = judge_answers(
            question,
            ground_truth,
            base_answer,
            rag_answer
        )

        # ----------------------------------------------------
        # STORE EVALUATION RESULTS
        # ----------------------------------------------------

        # Copy the original question and answers
        evaluated_item = item.copy()

        # Add the evaluation scores
        evaluated_item["evaluation"] = {

            "base": {
                "exact_match": base_exact,
                "token_f1": base_f1,
                "semantic_similarity": base_similarity
            },

            "rag": {
                "exact_match": rag_exact,
                "token_f1": rag_f1,
                "semantic_similarity": rag_similarity
            },

            "llm_judge": judge_result
        }

        # Add the evaluated question to the results list
        evaluated_results.append(evaluated_item)

        # Save after every question.
        # If the script stops unexpectedly, completed questions
        # will still be available in the output file.
        save_results(evaluated_results)

        print("Question evaluation completed.")

    return evaluated_results


# ------------------------------------------------------------
# 12. SAVE EVALUATION RESULTS
# ------------------------------------------------------------

def save_results(results):

    # Write the evaluation results to the output JSON file
    with open(OUTPUT_PATH, "w", encoding="utf-8") as file:

        json.dump(
            results,
            file,
            indent=4,
            ensure_ascii=False
        )


# ------------------------------------------------------------
# 13. MAIN FUNCTION
# ------------------------------------------------------------

def main():

    print("\nStarting evaluation...\n")

    # Load the original answers
    results = load_results()

    # Evaluate all questions
    evaluated_results = evaluate_results(results)

    # Save the final results
    save_results(evaluated_results)

    print("\n===================================")
    print("EVALUATION COMPLETED SUCCESSFULLY")
    print("===================================")

    print(f"Total questions evaluated: {len(evaluated_results)}")

    print(f"Results saved to:\n{OUTPUT_PATH}")


# ------------------------------------------------------------
# 14. RUN THE SCRIPT
# ------------------------------------------------------------

if __name__ == "__main__":
    main()
